// Get the Vision AI response
const visionResponse = $json.choices[0].message.content;

// Parse the JSON string
const visionAnalysis = JSON.parse(visionResponse);

// Return the parsed analysis
return {
  json: {
    vision_analysis: visionAnalysis
  }
};

const imageUrls = $json.image_url;

return {
  json: {
    model: "gpt-4o-mini",
    messages: [
      {
        role: "system",
        content: "You are a professional real estate property analyst. Analyze property photos and extract detailed features in structured JSON format."
      },
      {
        role: "user",
        content: [
          {
            type: "text",
            text: `Analyze ALL the provided property photos and extract detailed features.

Return ONLY valid JSON:
{
  "interior": {
    "flooring": "description",
    "kitchen": "features",
    "bathrooms": "features",
    "special_rooms": "features",
    "architectural_details": "details",
    "fireplace": "details"
  },
  "exterior": {
    "style": "style",
    "materials": "materials",
    "landscaping": "description",
    "outdoor_living": "features",
    "other": "garage, etc"
  },
  "condition": {
    "renovation_status": "status",
    "quality_level": "level",
    "maintenance": "condition"
  },
  "hero_photos": [
    {"rank": 1, "photo_filename": "extract filename from URL", "reason": "why", "confidence": 95}
  ]
}`
          },
          ...imageUrls.map(url => ({
            type: "image_url",
            image_url: { url: url }
          }))
        ]
      }
    ],
    response_format: { type: "json_object" },
    max_tokens: 2000
  }
};

// Get all image files from Google Drive
const imageFiles = $input.all();

// Build direct view URLs for each image
const imageUrls = imageFiles.map(item => {
  const fileId = item.json.id;
  const fileName = item.json.name;

  return {
    file_id: fileId,
    file_name: fileName,
    image_url: `https://drive.google.com/uc?export=view&id=${fileId}`
  };
});

// Return as array for Vision AI to process
return imageUrls.map(img => ({ json: img }));

// Get the AI response - it's in output[0].content[0].text
let parsedProperty;

if ($json.output && Array.isArray($json.output) && $json.output[0]) {
  const outputItem = $json.output[0];

  if (outputItem.content && Array.isArray(outputItem.content) && outputItem.content[0]) {
    parsedProperty = outputItem.content[0].text;
  }
}

// Validate we got the property data
if (!parsedProperty || !parsedProperty.address) {
  throw new Error('Could not find property data. Structure: ' + JSON.stringify($json).substring(0, 500));
}

// Get folder link from the Set node by name
const folderUrl = $('form_input').item.json.folder_link;

if (!folderUrl) {
  throw new Error('folder_link not found in form_input node');
}

// Extract folder ID from Google Drive URL
const match = folderUrl.match(/folders\/([a-zA-Z0-9_-]+)/);

if (!match || !match[1]) {
  throw new Error('Invalid Google Drive folder URL: ' + folderUrl);
}

// Return everything combined
return {
  json: {
    address: parsedProperty.address,
    city: parsedProperty.city,
    state: parsedProperty.state,
    zip: parsedProperty.zip,
    property_type: parsedProperty.property_type,
    bedrooms: parsedProperty.bedrooms,
    bathrooms: parsedProperty.bathrooms,
    square_footage: parsedProperty.square_footage,
    price: parsedProperty.price,
    year_built: parsedProperty.year_built,
    special_features: parsedProperty.special_features,
    folder_id: match[1],
    folder_url: folderUrl
  }
};

// Get property data from Extract Property Data node
const propertyData = $('Extract Property Data').item.json;

// Get vision analysis from Parse Vision Response node
const visionData = $('Parse Vision Response').item.json.vision_analysis;

// Get neighborhood data from sub-workflow
const neighborhoodData = $('Get Neighborhood Data').item.json;

// Merge everything into one object
return {
  json: {
    // Property basics
    address: propertyData.address,
    city: propertyData.city,
    state: propertyData.state,
    zip: propertyData.zip,
    property_type: propertyData.property_type,
    bedrooms: propertyData.bedrooms,
    bathrooms: propertyData.bathrooms,
    square_footage: propertyData.square_footage,
    price: propertyData.price,
    year_built: propertyData.year_built,
    special_features: propertyData.special_features,

    // Vision analysis from photos
    interior: visionData.interior,
    exterior: visionData.exterior,
    condition: visionData.condition,
    hero_photos: visionData.hero_photos,

    // Neighborhood data
    schools: neighborhoodData.schools,
    restaurants: neighborhoodData.restaurants,
    transportation: neighborhoodData.transportation
  }
};

