=Write a professional MLS listing description for this property:

ADDRESS: {{ $json.address }}, {{ $json.city }}, {{ $json.state }} {{ $json.zip }}
TYPE: {{ $json.property_type }}
BEDS/BATHS: {{ $json.bedrooms }} bed, {{ $json.bathrooms }} bath
SQUARE FOOTAGE: {{ $json.square_footage }} sq ft
PRICE: ${{ $json.price }}
YEAR BUILT: {{ $json.year_built }}

SPECIAL FEATURES:
{{ $json.special_features }}

INTERIOR (from photo analysis):
- Flooring: {{ $json.interior.flooring }}
- Kitchen: {{ $json.interior.kitchen }}
- Bathrooms: {{ $json.interior.bathrooms }}
- Special Rooms: {{ $json.interior.special_rooms }}
- Architectural Details: {{ $json.interior.architectural_details }}
- Fireplace: {{ $json.interior.fireplace }}

EXTERIOR (from photo analysis):
- Style: {{ $json.exterior.style }}
- Materials: {{ $json.exterior.materials }}
- Landscaping: {{ $json.exterior.landscaping }}
- Outdoor Living: {{ $json.exterior.outdoor_living }}
- Other: {{ $json.exterior.other }}

CONDITION:
- Renovation Status: {{ $json.condition.renovation_status }}
- Quality Level: {{ $json.condition.quality_level }}
- Maintenance: {{ $json.condition.maintenance }}

NEIGHBORHOOD & LOCATION:
Schools:
{{ $json.schools.nearby.map(s => `- ${s.name} (${s.type}, ${s.distance}, rated ${s.rating})`).join('\n') }}

Dining & Lifestyle:
- {{ $json.restaurants.count }} restaurants nearby
- Top rated: {{ $json.restaurants.top_rated.slice(0, 3).join(', ') }}

Transportation:
{{ $json.transportation.nearby_stops.length > 0 ? $json.transportation.nearby_stops.map(t => `- ${t.name} (${t.distance})`).join('\n') : '- Convenient access to public transit' }}

